import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def f_Kn(n):
    # Number of triangles in K_n: f(K_n) = C(n, 3)
    return combinations(n, 3)

def g_Kn(n):
    # Number of tetrahedra in K_n: g(K_n) = C(n, 4)
    return combinations(n, 4)

def R_Kn(n):
    f = f_Kn(n)
    g = g_Kn(n)

    if f == 0:
        return "Undefined (f=0)"

    # R(K_n) = g(K_n)^3 / f(K_n)^4
    return (g**3) / (f**4)

n_values = [10, 20, 50]
results = {}

print("--- Calculations for R(K_n) ---")
for n in n_values:
    r = R_Kn(n)
    results[n] = r
    f_val = f_Kn(n)
    g_val = g_Kn(n)
    print(f"n={n}:")
    print(f"  f(K_n) = {f_val}")
    print(f"  g(K_n) = {g_val}")
    print(f"  R(K_n) = {r}")

print("\n--- Summary ---")
for n, r in results.items():
    print(f"R(K_{n}) = {r}")

from math import comb

def calculate_R(n):
    if n < 4:
        return None
    f_n = comb(n, 3)
    g_n = comb(n, 4)
    # R(n) = g(K_n)^3 / f(K_n)^4
    return (g_n**3) / (f_n**4)

# Calculate R(n) for n from 4 to 20
R_values = {}
for n in range(4, 21):
    R_values[n] = calculate_R(n)

print("n, R(K_n)")
for n in sorted(R_values.keys()):
    print(f"{n}, {R_values[n]}")
